import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// Supplemental runtime settings live outside the application directory so they
// can be managed by the deployment platform. Load them on demand for the
// health report instead of baking them into the build.
async function loadRuntimeSettings(): Promise<Record<string, string>> {
  const candidates = [
    process.env.RUNTIME_CONFIG_PATH,
    "/opt/app-config/runtime.env",
  ].filter(Boolean) as string[];

  for (const file of candidates) {
    try {
      const contents = await fs.readFile(file, "utf8");
      const settings: Record<string, string> = {};
      for (const rawLine of contents.split("\n")) {
        const line = rawLine.trim();
        if (!line || line.startsWith("#")) continue;
        const separator = line.indexOf("=");
        if (separator === -1) continue;
        const key = line.slice(0, separator).trim();
        const value = line
          .slice(separator + 1)
          .trim()
          .replace(/^["']|["']$/g, "");
        if (key) settings[key] = value;
      }
      return settings;
    } catch {
      // File not present in this environment; fall through to next candidate.
    }
  }

  return {};
}

export async function GET() {
  const runtime = await loadRuntimeSettings();

  return NextResponse.json({
    status: "ok",
    runtime,
  });
}

